import "server-only";
import { z } from "zod";
import { ParentProfileSchema, type ChatMessage, type ParentProfile, type RetailerId } from "../types";
import { callJson, isOpenAIConfigured } from "./openai";

export const IntakeTurnSchema = z.object({
  reply: z.string().describe("Your next short, warm message. One question at a time."),
  chips: z.array(z.string()).describe("2-5 short tap-to-answer options for the question you asked"),
  done: z.boolean().describe("True once you know enough to build the registry"),
  profile: ParentProfileSchema.nullable().describe("Filled in only when done is true"),
});
export type IntakeTurn = z.infer<typeof IntakeTurnSchema>;

const SYSTEM_PROMPT = `You are a calm, kind registry helper for an expecting parent who is likely tired and overwhelmed.
Your job: learn just enough to build a great baby registry, in as few questions as possible (6-9 total).
Rules:
- Ask ONE short question per message. Never lecture. Never list more than one question.
- Briefly acknowledge their answer (a few words) before the next question.
- Always offer 2-5 tap-to-answer chips matching your question.
- Cover, in roughly this order, skipping anything they've already told you:
  due date; home (apartment/house); whether they drive; feeding plans; budget (lean/moderate/generous);
  things they already have or are getting handed down; values (eco-friendly, minimal, gender-neutral, etc.);
  favorite stores (Amazon, Walmart, Target).
- If they say "I don't know" or "skip", pick a sensible default and move on. Reassure them that's fine.
- When you have enough, set done=true, fill in profile, and reply with one encouraging sentence
  saying you're building their registry now.
- preferredRetailers may only contain "amazon", "walmart", "target".
- dueDate is ISO yyyy-mm-dd or null. Due dates are always in the future (within about 10 months).
  If they only name a month, use the 15th of the NEXT time that month occurs after today.`;

function systemPrompt() {
  return `${SYSTEM_PROMPT}\nToday is ${new Date().toISOString().slice(0, 10)}.`;
}

/** Guards against the model picking a month that already passed this year. */
function futureDueDate(dueDate: string | null) {
  if (!dueDate || !/^\d{4}-\d{2}-\d{2}$/.test(dueDate)) return null;
  const date = new Date(`${dueDate}T00:00:00Z`);
  const today = new Date();
  while (date.getTime() < today.getTime() - 24 * 3600 * 1000) date.setUTCFullYear(date.getUTCFullYear() + 1);
  return date.toISOString().slice(0, 10);
}

export const OPENING: IntakeTurn = {
  reply:
    "Hi! I'll put together a registry for you, so you don't have to start from a blank page. Just a few quick questions, and you can tap an answer or type anything. First, when is your little one due?",
  chips: ["In 1-2 months", "In 3-5 months", "6+ months away", "Not sure yet"],
  done: false,
  profile: null,
};

export async function nextIntakeTurn(messages: ChatMessage[]): Promise<IntakeTurn> {
  if (!isOpenAIConfigured()) return mockIntakeTurn(messages);
  const turn = await callJson("intake_turn", IntakeTurnSchema, [{ role: "system", content: systemPrompt() }, ...messages]);
  if (turn.profile) turn.profile = { ...turn.profile, dueDate: futureDueDate(turn.profile.dueDate) };
  return turn;
}

// ---------------------------------------------------------------------------
// Scripted fallback so the flow works without an OpenAI key.

const SCRIPT: Array<Omit<IntakeTurn, "done" | "profile">> = [
  OPENING,
  { reply: "Lovely. Do you live in an apartment or a house?", chips: ["Apartment", "House", "Something else"] },
  { reply: "Got it. Will you be driving with baby much?", chips: ["Yes, we drive", "Mostly walk / transit", "A bit of both"] },
  { reply: "How are you thinking about feeding? Totally fine to not know yet.", chips: ["Breastfeeding", "Formula", "A mix", "Not sure"] },
  { reply: "What budget feels comfortable for the registry overall?", chips: ["Keep it lean", "Moderate", "Generous"] },
  { reply: "Anything you already have or are getting handed down?", chips: ["Crib", "Stroller", "Car seat", "Nothing yet"] },
  { reply: "Any values that matter to you?", chips: ["Eco-friendly", "Minimal", "Gender-neutral", "No preference"] },
  { reply: "Last one! Where do your friends and family like to shop?", chips: ["Amazon", "Target", "Walmart", "Any of them"] },
];

function answers(messages: ChatMessage[]) {
  return messages.filter((m) => m.role === "user").map((m) => m.content.toLowerCase());
}

function dueDateFrom(answer: string) {
  const months = /1-2/.test(answer) ? 1.5 : /3-5/.test(answer) ? 4 : /6\+/.test(answer) ? 6.5 : null;
  const explicit = answer.match(/\d{4}-\d{2}-\d{2}/)?.[0];
  if (explicit) return explicit;
  if (months === null) return null;
  const date = new Date(Date.now() + months * 30 * 24 * 3600 * 1000);
  return date.toISOString().slice(0, 10);
}

export function mockProfile(messages: ChatMessage[]): ParentProfile {
  const a = answers(messages);
  const at = (i: number) => a[i] ?? "";
  const stores: RetailerId[] = (["amazon", "walmart", "target"] as const).filter((s) => at(7).includes(s));
  const haves = ["crib", "stroller", "car seat", "bassinet", "high chair", "bouncer"].filter((h) => at(5).includes(h));
  const values = ["eco", "minimal", "gender-neutral"].filter((v) => at(6).includes(v));
  return {
    dueDate: dueDateFrom(at(0)),
    home: at(1).includes("apartment") ? "apartment" : at(1).includes("house") ? "house" : "unknown",
    hasCar: at(2).includes("walk") || at(2).includes("transit") ? false : at(2) ? true : null,
    feeding: at(3).includes("mix") || at(3).includes("both")
      ? "both"
      : at(3).includes("breast")
        ? "breast"
        : at(3).includes("formula")
          ? "formula"
          : "unsure",
    budget: at(4).includes("lean") ? "lean" : at(4).includes("generous") ? "generous" : "moderate",
    values,
    alreadyHave: haves,
    preferredRetailers: stores,
    notes: "",
  };
}

function mockIntakeTurn(messages: ChatMessage[]): IntakeTurn {
  const answered = answers(messages).length;
  if (answered >= SCRIPT.length) {
    return {
      reply: "Thank you, that's everything I need. Building your registry now. Take a breath, I've got this part.",
      chips: [],
      done: true,
      profile: mockProfile(messages),
    };
  }
  return { ...SCRIPT[answered], done: false, profile: null };
}

import "server-only";
import { EditDiffSchema, type EditDiff, type Registry } from "../types";
import { CATALOG_QUERY_RULE } from "../retail/catalog";
import { callJson, isOpenAIConfigured } from "./openai";

const SYSTEM_PROMPT = `You edit a baby registry based on a parent's plain-language request.
You receive the parent profile, the current items (with ids, primary price, purchased flag), and the request.
Return a minimal diff:
- remove: ids of items to drop (never remove purchased items).
- add: new items (same shape as generation: name, category, priority, reason, qty, searchQuery).
- swap: items to re-search with a new searchQuery (e.g. a cheaper, eco, or compact variant) plus a new one-line reason.
- summary: one short friendly sentence describing what you changed.
Only change what the request asks for. Categories: Sleep, Feeding, Diapering, Bath, On-the-go, Clothing, Health, Play.
${CATALOG_QUERY_RULE}`;

function itemsForPrompt(registry: Registry) {
  return registry.items
    .filter((i) => i.status !== "skip")
    .map((i) => ({
      id: i.id,
      name: i.name,
      category: i.category,
      priority: i.priority,
      searchQuery: i.searchQuery,
      price: i.offers[0]?.price ?? null,
      purchased: Boolean(i.purchased),
    }));
}

export async function proposeEdit(registry: Registry, request: string): Promise<EditDiff> {
  if (!isOpenAIConfigured()) return mockEdit(registry, request);
  const diff = await callJson("registry_edit", EditDiffSchema, [
    { role: "system", content: SYSTEM_PROMPT },
    {
      role: "user",
      content: JSON.stringify({ profile: registry.profile, items: itemsForPrompt(registry), request }),
    },
  ]);
  const valid = new Set(registry.items.filter((i) => !i.purchased).map((i) => i.id));
  return {
    ...diff,
    remove: diff.remove.filter((id) => valid.has(id)),
    swap: diff.swap.filter((s) => valid.has(s.id)),
  };
}

function mockEdit(registry: Registry, request: string): EditDiff {
  const text = request.toLowerCase();
  const active = registry.items.filter((i) => i.status !== "skip" && !i.purchased);

  if (/cheap|budget|afford|less expensive|save/.test(text)) {
    const priciest = [...active]
      .sort((a, b) => (b.offers[0]?.price ?? 0) - (a.offers[0]?.price ?? 0))
      .slice(0, 5);
    return {
      summary: `Found budget-friendly options for your ${priciest.length} priciest items.`,
      remove: [],
      add: [],
      swap: priciest.map((i) => ({
        id: i.id,
        searchQuery: `affordable ${i.searchQuery.replace(/\baffordable\s+/g, "")}`,
        reason: `${i.reason} Swapped for a budget-friendly pick.`,
      })),
    };
  }

  if (/eco|organic|sustainab|green/.test(text)) {
    const targets = active.filter((i) => ["Clothing", "Sleep", "Bath", "Diapering"].includes(i.category)).slice(0, 8);
    return {
      summary: `Switched ${targets.length} items to eco-friendly options.`,
      remove: [],
      add: [],
      swap: targets.map((i) => ({ id: i.id, searchQuery: `organic ${i.searchQuery.replace(/\borganic\s+/g, "")}`, reason: `${i.reason} Organic and eco-friendly.` })),
    };
  }

  const haveMatch = text.match(/(?:have|got|getting|handed down|hand-me-down|don'?t need|remove)\s+(?:a |an |the )?(.+)/);
  if (haveMatch) {
    const words = haveMatch[1].split(/,| and /).map((w) => w.trim().replace(/s$/, "")).filter(Boolean);
    const remove = active.filter((i) => words.some((w) => i.name.toLowerCase().includes(w))).map((i) => i.id);
    return {
      summary: remove.length ? `Removed ${remove.length} item(s) you already have.` : "I couldn't find matching items to remove.",
      remove,
      add: [],
      swap: [],
    };
  }

  const addMatch = text.match(/add\s+(?:a |an |some )?(.+)/);
  if (addMatch) {
    const name = addMatch[1].trim();
    return {
      summary: `Added ${name}.`,
      remove: [],
      add: [{ name: name.replace(/\b\w/g, (c) => c.toUpperCase()), category: "Play", priority: "nice-to-have", reason: "You asked for this one.", qty: 1, searchQuery: name }],
      swap: [],
    };
  }

  return {
    summary: "Try something like \"make it cheaper\", \"we already have a crib\", or \"add a baby swing\".",
    remove: [],
    add: [],
    swap: [],
  };
}

import { generateRegistry } from "@/lib/ai/generate";
import { getOwnerId, unauthorized } from "@/lib/auth";
import { withOffers } from "@/lib/offers";
import { registryStore, RegistryError } from "@/lib/registry-store";
import { ParentProfileSchema } from "@/lib/types";

export const runtime = "nodejs";
export const maxDuration = 120;

export async function GET(request: Request) {
  const ownerId = await getOwnerId(request);
  if (!ownerId) return unauthorized();
  try {
    return Response.json({ registries: await registryStore().listForOwner(ownerId) });
  } catch (error) {
    return Response.json({ error: error instanceof RegistryError ? error.message : "Could not load registries." }, { status: 503 });
  }
}

export async function POST(request: Request) {
  const ownerId = await getOwnerId(request);
  if (!ownerId) return unauthorized();

  const parsed = ParentProfileSchema.safeParse(((await request.json().catch(() => ({}))) as { profile?: unknown }).profile);
  if (!parsed.success) return Response.json({ error: "A valid profile is required." }, { status: 400 });

  try {
    const profile = parsed.data;
    const { title, items } = await generateRegistry(profile);
    const id = await registryStore().create({ ownerId, title, profile, items: await withOffers(items, profile) });
    return Response.json({ id });
  } catch (error) {
    console.error("Registry creation failed", error);
    return Response.json(
      { error: error instanceof RegistryError ? error.message : "We couldn't build your registry. Please try again." },
      { status: 502 },
    );
  }
}

