// Headless check of the voice agent Settings: no mic, typed user messages only.
// Usage: node --conditions=react-server node_modules/.bin/jiti /tmp/calm-voice-test/agent-test.ts [intake|edit] [baseUrl]
import { readFileSync } from "node:fs";

const ROOT = "/Users/rizelscarlett/Documents/agent-experiments/baby-registry";
for (const line of readFileSync(`${ROOT}/.env.local`, "utf8").split("\n")) {
  const m = line.match(/^([A-Z_]+)=(.*)$/);
  if (m && !process.env[m[1]]) process.env[m[1]] = m[2].replace(/^"|"$/g, "");
}

const mode = (process.argv[2] ?? "intake") as "intake" | "edit";

async function main() {
  const { intakeSettings, editSettings, AGENT_URL } = await import(`${ROOT}/lib/voice/settings.ts`);
  const { ParentProfileSchema } = await import(`${ROOT}/lib/types.ts`);

  let settings: unknown;
  let say: string;
  if (mode === "intake") {
    ({ settings } = intakeSettings([]));
    say =
      "Our baby is due next March. We live in a small apartment, we don't have a car and take the subway. " +
      "Planning to breastfeed. Keep the budget lean. My sister is giving us her crib. " +
      "We care about eco-friendly stuff, and family mostly shops at Target. That's everything, please build it.";
  } else {
    const { registryStore } = await import(`${ROOT}/lib/registry-store.ts`);
    const store = registryStore();
    const data = JSON.parse(readFileSync(`${ROOT}/.data/registries.json`, "utf8"));
    const first = (Array.isArray(data) ? data : (data.registries ?? Object.values(data)))[0];
    const registry = await store.getById(first.id);
    if (!registry) throw new Error("no local registry to edit");
    ({ settings } = editSettings(registry));
    say = "We're getting a hand-me-down stroller from my cousin, so take the stroller off.";
  }
  console.log(`settings: ${JSON.stringify(settings).length} chars`);

  const ws = new WebSocket(AGENT_URL, ["token", process.env.DEEPGRAM_API_KEY!]);
  ws.binaryType = "arraybuffer";
  let audioBytes = 0;
  let injected = false;
  const done = (code: number) => {
    console.log(`audio received: ${audioBytes} bytes`);
    ws.close();
    process.exit(code);
  };
  setTimeout(() => {
    console.log("TIMEOUT");
    done(1);
  }, 45000);

  const inject = () => {
    if (injected) return;
    injected = true;
    console.log(`> user: ${say}`);
    ws.send(JSON.stringify({ type: "InjectUserMessage", content: say }));
  };

  ws.onmessage = (e) => {
    if (e.data instanceof ArrayBuffer) {
      audioBytes += e.data.byteLength;
      return;
    }
    const event = JSON.parse(String(e.data));
    if (!["History"].includes(event.type)) console.log(`< ${event.type}${event.role ? ` (${event.role})` : ""}${event.content ? `: ${event.content}` : ""}`);
    if (event.type === "Welcome") ws.send(JSON.stringify(settings));
    if (event.type === "AgentAudioDone") inject();
    if (event.type === "Error") done(1);
    if (event.type === "FunctionCallRequest") {
      for (const call of event.functions) {
        console.log(`  function ${call.name} client_side=${call.client_side} args=${call.arguments}`);
        if (call.name === "finish_intake") {
          const parsed = ParentProfileSchema.safeParse(JSON.parse(call.arguments));
