// Supabase implementation

type ItemRow = {
  id: string;
  name: string;
  category: RegistryItem["category"];
  priority: RegistryItem["priority"];
  reason: string;
  qty: number;
  status: ItemStatus;
  position: number;
  search_query: string;
  item_offers: Array<{
    id: string;
    retailer: RetailerId;
    external_id: string;
    title: string;
    price: number | string | null;
    image_url: string | null;
    url: string;
    rating: number | string | null;
    in_stock: boolean;
    is_primary: boolean;
  }>;
  purchases: Array<{ buyer_name: string | null; retailer: RetailerId | null }> | { buyer_name: string | null; retailer: RetailerId | null } | null;
};

type RegistryRow = {
  id: string;
  slug: string;
  owner_id: string;
  title: string;
  profile: ParentProfile;
  preferred_retailers: RetailerId[];
  due_date: string | null;
  revision: number | string;
  registry_items: ItemRow[];
};

const REGISTRY_SELECT =
  "id, slug, owner_id, title, profile, preferred_retailers, due_date, revision, registry_items(id, name, category, priority, reason, qty, status, position, search_query, item_offers(*), purchases(buyer_name, retailer))";

function toRegistry(row: RegistryRow): Registry {
  const items = [...row.registry_items]
    .sort((a, b) => a.position - b.position)
    .map((item): RegistryItem => {
      const purchase = Array.isArray(item.purchases) ? item.purchases[0] : item.purchases;
      return {
        id: item.id,
        name: item.name,
        category: item.category,
        priority: item.priority,
        reason: item.reason,
        qty: item.qty,
        status: item.status,
        position: item.position,
        searchQuery: item.search_query,
        offers: [...item.item_offers]
          .sort((a, b) => Number(b.is_primary) - Number(a.is_primary))
          .map((o) => ({
            id: o.id,
            retailer: o.retailer,
            externalId: o.external_id,
            title: o.title,
            price: o.price === null ? null : Number(o.price),
            imageUrl: o.image_url,
            url: o.url,
            rating: o.rating === null ? null : Number(o.rating),
            inStock: o.in_stock,
            isPrimary: o.is_primary,
          })),
        purchased: purchase ? { buyerName: purchase.buyer_name, retailer: purchase.retailer } : null,
      };
    });
  return {
    id: row.id,
    slug: row.slug,
    ownerId: row.owner_id,
    title: row.title,
    profile: row.profile,
    preferredRetailers: row.preferred_retailers,
    dueDate: row.due_date,
    revision: Number(row.revision),
    items,
  };
}

const supabaseStore = {
  async create(input: CreateRegistryInput) {
    for (let attempt = 0; attempt < 5; attempt += 1) {
      const { data, error } = await getSupabaseAdmin()
        .rpc("registry_create", {
          p_owner_id: input.ownerId,
          p_slug: makeSlug(input.title),
          p_title: input.title,
          p_profile: input.profile,
          p_preferred_retailers: input.profile.preferredRetailers,
          p_due_date: input.profile.dueDate,
          p_items: input.items,
        })
        .single();
      if (!error && data) return (data as { id: string }).id;
      if (error?.code !== "23505") throw new RegistryError(friendlyError(error?.message));
    }
    throw new RegistryError("A unique link could not be created. Please try again.");
  },

  async getById(id: string) {
    const { data, error } = await getSupabaseAdmin().from("registries").select(REGISTRY_SELECT).eq("id", id).maybeSingle();
    if (error) throw new RegistryError(friendlyError(error.message));
    return data ? toRegistry(data as unknown as RegistryRow) : null;
  },

  async getBySlug(slug: string) {
    const { data, error } = await getSupabaseAdmin().from("registries").select(REGISTRY_SELECT).eq("slug", slug).maybeSingle();
    if (error) throw new RegistryError(friendlyError(error.message));
    return data ? toRegistry(data as unknown as RegistryRow) : null;
  },

  async listForOwner(ownerId: string) {
    const { data, error } = await getSupabaseAdmin()
      .from("registries")
      .select("id, slug, title, created_at")
      .eq("owner_id", ownerId)
      .order("created_at", { ascending: false });
    if (error) throw new RegistryError(friendlyError(error.message));
    return (data ?? []) as Array<{ id: string; slug: string; title: string }>;
  },

  async rpc(name: string, args: Record<string, unknown>) {
    const { error } = await getSupabaseAdmin().rpc(name, args);
    if (error) throw new RegistryError(friendlyError(error.message));
  },

  async setItemStatus(registryId: string, ownerId: string, itemId: string, status: ItemStatus) {
    await this.rpc("registry_set_item_status", {
      p_registry_id: registryId,
      p_owner_id: ownerId,
      p_item_id: itemId,
      p_status: status,
    });
  },

  async setPrimaryOffer(registryId: string, ownerId: string, itemId: string, offerId: string) {
    await this.rpc("registry_set_primary_offer", {
      p_registry_id: registryId,
      p_owner_id: ownerId,
      p_item_id: itemId,
      p_offer_id: offerId,
    });
  },

  async applyEdits(registryId: string, ownerId: string, remove: string[], add: NewItem[], swaps: OfferSwap[]) {
    await this.rpc("registry_apply_edits", {
      p_registry_id: registryId,
      p_owner_id: ownerId,
      p_remove: remove,
      p_add: add,
      p_replace_offers: swaps,
    });
  },

  async markPurchased(slug: string, itemId: string, buyerName: string | null, retailer: RetailerId | null) {
    await this.rpc("registry_mark_purchased", {
      p_slug: slug,
      p_item_id: itemId,
      p_buyer_name: buyerName,
      p_retailer: retailer,
    });
  },
};

// ---------------------------------------------------------------------------
// Local JSON-file implementation, used only when Supabase is not configured so
// the app can be tried end to end without any accounts.

const LOCAL_FILE = path.join(process.cwd(), ".data", "registries.json");

async function readLocal(): Promise<Registry[]> {
  try {
    return JSON.parse(await fs.readFile(LOCAL_FILE, "utf8")) as Registry[];
  } catch {
    return [];
  }
}

async function writeLocal(registries: Registry[]) {
  await fs.mkdir(path.dirname(LOCAL_FILE), { recursive: true });
  await fs.writeFile(LOCAL_FILE, JSON.stringify(registries, null, 2));
}

function toLocalItem(item: NewItem, position: number): RegistryItem {
  return {
    id: crypto.randomUUID(),
    name: item.name,
    category: item.category,
    priority: item.priority,
    reason: item.reason,
    qty: item.qty,
    status: "pending",
    position,
    searchQuery: item.searchQuery,
    offers: item.offers.map((o, i) => ({ ...o, id: crypto.randomUUID(), isPrimary: i === 0 })),
    purchased: null,
  };
}

async function mutateLocal(registryId: string, ownerId: string, fn: (r: Registry) => void) {
  const all = await readLocal();
  const registry = all.find((r) => r.id === registryId && r.ownerId === ownerId);
  if (!registry) throw new RegistryError("Registry not found.");
  fn(registry);
  registry.revision += 1;
  await writeLocal(all);
}

function findItem(registry: Registry, itemId: string) {
  const item = registry.items.find((i) => i.id === itemId);
  if (!item) throw new RegistryError("That item is not on this registry.");
  return item;
}

const localStore: typeof supabaseStore = {
  async create(input) {
    const all = await readLocal();
    const registry: Registry = {
      id: crypto.randomUUID(),
      slug: makeSlug(input.title),
      ownerId: input.ownerId,
      title: input.title,
      profile: input.profile,
      preferredRetailers: input.profile.preferredRetailers,
      dueDate: input.profile.dueDate,
      revision: 0,
      items: input.items.map(toLocalItem),
    };
    all.push(registry);
    await writeLocal(all);
    return registry.id;
  },
  async getById(id) {
    return (await readLocal()).find((r) => r.id === id) ?? null;
  },
  async getBySlug(slug) {
    return (await readLocal()).find((r) => r.slug === slug) ?? null;
  },
  async listForOwner(ownerId) {
    return (await readLocal())
      .filter((r) => r.ownerId === ownerId)
      .reverse()
      .map(({ id, slug, title }) => ({ id, slug, title }));
  },
  async rpc() {},
  async setItemStatus(registryId, ownerId, itemId, status) {
    await mutateLocal(registryId, ownerId, (r) => {
      findItem(r, itemId).status = status;
    });
  },
  async setPrimaryOffer(registryId, ownerId, itemId, offerId) {
    await mutateLocal(registryId, ownerId, (r) => {
      const item = findItem(r, itemId);
      if (!item.offers.some((o) => o.id === offerId)) throw new RegistryError("That item is not on this registry.");
      item.offers.forEach((o) => (o.isPrimary = o.id === offerId));
      item.offers.sort((a, b) => Number(b.isPrimary) - Number(a.isPrimary));
    });
  },
  async applyEdits(registryId, ownerId, remove, add, swaps) {
    await mutateLocal(registryId, ownerId, (r) => {
      r.items = r.items.filter((i) => !remove.includes(i.id) || i.purchased);
      for (const swap of swaps) {
        const item = r.items.find((i) => i.id === swap.itemId);
        if (!item) continue;
        item.searchQuery = swap.searchQuery;
        item.reason = swap.reason;
        item.status = "pending";
        item.offers = swap.offers.map((o, i) => ({ ...o, id: crypto.randomUUID(), isPrimary: i === 0 }));
      }
      const start = r.items.reduce((max, i) => Math.max(max, i.position), -1) + 1;
      r.items.push(...add.map((item, i) => toLocalItem(item, start + i)));
    });
  },
  async markPurchased(slug, itemId, buyerName, retailer) {
    const all = await readLocal();
    const registry = all.find((r) => r.slug === slug);
    if (!registry) throw new RegistryError("Registry not found.");
    const item = findItem(registry, itemId);
    if (item.status === "skip") throw new RegistryError("That item is not on this registry.");
    if (item.purchased) throw new RegistryError("Someone already bought this one.");
    item.purchased = { buyerName: buyerName?.trim() || null, retailer };
    registry.revision += 1;
    await writeLocal(all);
  },
};

export function registryStore() {
  return isSupabaseConfigured() ? supabaseStore : localStore;
}

import { registryStore, RegistryError } from "@/lib/registry-store";
import { RETAILERS, type Registry, type RetailerId } from "@/lib/types";

export const runtime = "nodejs";

type RouteContext = { params: Promise<{ slug: string }> };

type PublicRegistry = Omit<Registry, "ownerId" | "profile">;

function toPublic(registry: Registry): PublicRegistry {
  const { ownerId: _owner, profile: _profile, ...rest } = registry;
  return {
    ...rest,
    items: rest.items
      .filter((i) => i.status !== "skip")
      .map((i) => ({ ...i, purchased: i.purchased ? { buyerName: null, retailer: null } : null })),
  };
}

export async function GET(_request: Request, context: RouteContext) {
  const { slug } = await context.params;
  try {
    const registry = await registryStore().getBySlug(slug);
    if (!registry) return Response.json({ error: "Registry not found." }, { status: 404 });
    return Response.json({ registry: toPublic(registry) }, { headers: { "Cache-Control": "no-store" } });
  } catch (error) {
    return Response.json({ error: error instanceof RegistryError ? error.message : "Could not load registry." }, { status: 503 });
  }
}

export async function POST(request: Request, context: RouteContext) {
  const { slug } = await context.params;
  const body = (await request.json().catch(() => ({}))) as { itemId?: string; buyerName?: string; retailer?: string };
  if (!body.itemId) return Response.json({ error: "Which item did you buy?" }, { status: 400 });
  const retailer = RETAILERS.includes(body.retailer as RetailerId) ? (body.retailer as RetailerId) : null;

  try {
    await registryStore().markPurchased(slug, body.itemId, body.buyerName?.slice(0, 80) ?? null, retailer);
    return Response.json({ ok: true });
  } catch (error) {
    return Response.json({ error: error instanceof RegistryError ? error.message : "Could not mark as purchased." }, { status: 409 });
  }
}

import { getOwnerId, unauthorized } from "@/lib/auth";
import { registryStore, RegistryError } from "@/lib/registry-store";
import type { ItemStatus } from "@/lib/types";

export const runtime = "nodejs";

type RouteContext = { params: Promise<{ id: string }> };
type Action =
  | { action: "status"; itemId: string; status: ItemStatus }
  | { action: "primary"; itemId: string; offerId: string };

const STATUSES: ItemStatus[] = ["pending", "keep", "skip"];

export async function GET(request: Request, context: RouteContext) {
  const { id } = await context.params;
  const ownerId = await getOwnerId(request);
  if (!ownerId) return unauthorized();
  try {
    const registry = await registryStore().getById(id);
    if (!registry || registry.ownerId !== ownerId) return Response.json({ error: "Registry not found." }, { status: 404 });
    return Response.json({ registry }, { headers: { "Cache-Control": "no-store" } });
  } catch (error) {
    return Response.json({ error: error instanceof RegistryError ? error.message : "Could not load registry." }, { status: 503 });
  }
}

export async function PATCH(request: Request, context: RouteContext) {
  const { id } = await context.params;
  const ownerId = await getOwnerId(request);
  if (!ownerId) return unauthorized();

  const input = (await request.json().catch(() => null)) as Action | null;
  try {
    const store = registryStore();
    if (input?.action === "status" && STATUSES.includes(input.status)) {
      await store.setItemStatus(id, ownerId, input.itemId, input.status);
    } else if (input?.action === "primary" && input.offerId) {
      await store.setPrimaryOffer(id, ownerId, input.itemId, input.offerId);
    } else {
      return Response.json({ error: "Unknown action." }, { status: 400 });
    }
    return Response.json({ ok: true });
  } catch (error) {
    return Response.json({ error: error instanceof RegistryError ? error.message : "Could not update." }, { status: 409 });
  }
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { api } from "@/lib/client";
import type { ItemStatus, Registry } from "@/lib/types";

export function useRegistry(id: string) {
  const [registry, setRegistry] = useState<Registry | null>(null);
  const [error, setError] = useState("");

  const reload = useCallback(async () => {
    try {
      const { registry } = await api<{ registry: Registry }>(`/api/registries/${id}`);
      setRegistry(registry);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Could not load registry.");
    }
  }, [id]);

  useEffect(() => {
    void reload();
  }, [reload]);

  const setStatus = useCallback(
    async (itemId: string, status: ItemStatus) => {
      setRegistry((r) => r && { ...r, items: r.items.map((i) => (i.id === itemId ? { ...i, status } : i)) });
      await api(`/api/registries/${id}`, { method: "PATCH", body: JSON.stringify({ action: "status", itemId, status }) }).catch(
        (e: Error) => setError(e.message),
      );
    },
    [id],
  );

  const setPrimary = useCallback(
    async (itemId: string, offerId: string) => {
      setRegistry(
        (r) =>
          r && {
            ...r,
            items: r.items.map((i) =>
              i.id === itemId
                ? {
                    ...i,
                    offers: i.offers
                      .map((o) => ({ ...o, isPrimary: o.id === offerId }))
                      .sort((a, b) => Number(b.isPrimary) - Number(a.isPrimary)),
                  }
                : i,
            ),
          },
      );
      await api(`/api/registries/${id}`, { method: "PATCH", body: JSON.stringify({ action: "primary", itemId, offerId }) }).catch(
        (e: Error) => setError(e.message),
      );
    },
    [id],
  );

  return { registry, error, reload, setStatus, setPrimary };
}

"use client";

import { use, useCallback, useEffect, useState } from "react";
import { ProductPhoto } from "@/components/ProductPhoto";
import { Status } from "@/components/Status";
import { formatPrice, getBrowserSupabase } from "@/lib/client";
import { CATEGORIES, RETAILER_LABELS, type Registry, type RegistryItem, type RetailerId } from "@/lib/types";

type PublicRegistry = Omit<Registry, "ownerId" | "profile">;

const POLL_MS = 15000;

export default function SharePage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = use(params);
  return (
    <div data-theme="day">
      <Gifts slug={slug} />
    </div>
  );
}

function Gifts({ slug }: { slug: string }) {
  const [registry, setRegistry] = useState<PublicRegistry | null>(null);
  const [error, setError] = useState("");

  const load = useCallback(async () => {
    const response = await fetch(`/api/r/${slug}`, { cache: "no-store" });
    const data = (await response.json()) as { registry?: PublicRegistry; error?: string };
    if (data.registry) setRegistry(data.registry);
    else setError(data.error ?? "This registry link doesn't work. Ask the parents for a new one.");
  }, [slug]);

  useEffect(() => {
    void load();
    // Poll even when realtime is available, so the page still updates if broadcasts are down.
    const timer = setInterval(() => void load(), POLL_MS);
    const supabase = getBrowserSupabase();
    const channel = supabase
      ?.channel(`registry:${slug}`)
      .on("broadcast", { event: "registry_changed" }, () => void load())
      .subscribe();
    return () => {
      clearInterval(timer);
      if (supabase && channel) void supabase.removeChannel(channel);
    };
  }, [load, slug]);

  if (error) return <Status>{error}</Status>;
  if (!registry) return <Status>Opening the registry…</Status>;

  const open = registry.items.filter((i) => !i.purchased);
  const gifted = registry.items.filter((i) => i.purchased);

  return (
    <main className="space-y-12 pt-10 lg:pt-16">
      <header className="max-w-2xl space-y-3">
        <h1 className="font-serif text-[33px] leading-tight font-semibold lg:text-[48px] lg:leading-[1.1]">{registry.title}</h1>
        <p className="text-muted">
          {registry.dueDate &&
            `Due ${new Date(registry.dueDate + "T00:00:00").toLocaleDateString(undefined, { month: "long", year: "numeric" })}. `}
          {gifted.length} of {registry.items.length} gifted so far.
        </p>
        <p className="max-w-[52ch] font-serif text-[17px] leading-relaxed text-note italic">
          Buy from any store you like. When you do, mark it here so nobody else buys the same thing.
        </p>
      </header>

      {CATEGORIES.map((category) => {
        const items = open.filter((i) => i.category === category);
        if (!items.length) return null;
        return (
          <section key={category} aria-labelledby={`gift-${category}`}>
            <h2 id={`gift-${category}`} className="border-b border-line pb-3 font-serif text-[21px] font-semibold">
              {category}
            </h2>
            <ul className="grid gap-x-8 sm:grid-cols-2 sm:gap-y-4 lg:grid-cols-3 2xl:grid-cols-4">
              {items.map((item) => (
                <GiftRow key={item.id} item={item} slug={slug} onBought={load} />
              ))}
            </ul>
          </section>
        );
      })}

      {gifted.length > 0 && (
        <section aria-labelledby="gift-done">
          <h2 id="gift-done" className="border-b border-line pb-3 font-serif text-[21px] font-semibold">
            Already gifted
          </h2>
          <ul className="grid gap-x-8 sm:grid-cols-2 lg:grid-cols-3 2xl:grid-cols-4">
            {gifted.map((item) => (
              <li key={item.id} className="flex items-center gap-4 border-b border-line py-3 text-muted">
                <ProductPhoto offer={item.offers[0]} label={item.name} className="h-12 w-12 opacity-70" />
                <span className="flex-1">{item.name}</span>
                <span className="rounded-md bg-gift-bg px-2 py-0.5 text-[13px] text-gift">Gifted</span>
              </li>
            ))}
          </ul>
        </section>
      )}
    </main>
  );
}

function GiftRow({ item, slug, onBought }: { item: RegistryItem; slug: string; onBought: () => Promise<void> }) {
  const [confirming, setConfirming] = useState<RetailerId | "elsewhere" | null>(null);
  const [name, setName] = useState("");
  const [error, setError] = useState("");
  const primary = item.offers[0];

  async function markBought() {
    setError("");
    const response = await fetch(`/api/r/${slug}`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ itemId: item.id, buyerName: name, retailer: confirming === "elsewhere" ? null : confirming }),
    });
    const data = (await response.json()) as { error?: string };
    if (!response.ok) setError(data.error ?? "This gift couldn't be marked. Try again.");
    setConfirming(null);
    await onBought();
  }

  return (
    <li className="flex flex-col gap-4 border-b border-line py-5 sm:border-0 sm:pt-6 sm:pb-2">
      <div className="flex gap-4 sm:flex-col">
        <ProductPhoto offer={primary} label={item.name} className="h-24 w-24 sm:aspect-[4/3] sm:h-auto sm:w-full" />
        <div className="min-w-0 flex-1 space-y-1">
          <p className="font-semibold">
            {item.name}
            {item.qty > 1 && <span className="font-normal text-muted"> ×{item.qty}</span>}
          </p>
          {primary && <p className="line-clamp-2 text-[13px] text-muted">{primary.title}</p>}
          <p className="font-serif text-[14px] leading-snug text-note italic">{item.reason}</p>
        </div>
      </div>

      {confirming ? (
        <div className="space-y-3 rounded-xl bg-surface p-4 sm:mt-auto" style={{ boxShadow: "0 0 0 1px var(--line)" }}>
          <p>Did you buy it? Marking it lets everyone know it&apos;s covered.</p>
          <label htmlFor={`buyer-${item.id}`} className="sr-only">
            Your name
          </label>
          <input
            id={`buyer-${item.id}`}
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="Your name (optional)"
            className="field"
          />
          <div className="flex gap-2">
            <button className="btn-quiet flex-1 py-2.5" onClick={() => setConfirming(null)}>
              Not yet
            </button>
            <button className="btn-primary flex-1 py-2.5" onClick={() => void markBought()}>
              Mark as bought
            </button>
          </div>
        </div>
      ) : (
        <div className="flex flex-wrap items-center gap-2 sm:mt-auto">
          {/* Only the product the parents chose: other offers can be different products. */}
          {primary && (
            <a
              href={primary.url}
              target="_blank"
              rel="noopener noreferrer sponsored"
              onClick={() => setConfirming(primary.retailer)}
              className="btn-primary px-4 py-2 text-[14px]"
            >
              {primary.price === null
                ? `Shop at ${RETAILER_LABELS[primary.retailer]}`
                : `${formatPrice(primary.price)} at ${RETAILER_LABELS[primary.retailer]}`}
            </a>
          )}
          <button className="link ml-1 text-[13px]" onClick={() => setConfirming("elsewhere")}>
            I bought it somewhere else
          </button>
        </div>
      )}
      {error && (
        <p role="alert" className="text-[13px] text-danger">
          {error}
        </p>
      )}
    </li>
  );
}

