// Smoke test for names, details, and the address request flow against a running app.
const base = process.argv[2] ?? "http://localhost:3000";
const auth = process.env.ACCESS_TOKEN ? { authorization: `Bearer ${process.env.ACCESS_TOKEN}` } : {};
const json = { "content-type": "application/json", ...auth };
let failures = 0;
const check = (label, ok, extra = "") => {
  console.log(`${ok ? "PASS" : "FAIL"} ${label}${extra ? ` ${extra}` : ""}`);
  if (!ok) failures++;
};
const call = async (path, init = {}) => {
  const res = await fetch(base + path, { ...init, headers: { ...json, ...(init.headers ?? {}) } });
  return { status: res.status, body: await res.json().catch(() => ({})) };
};

const profile = {
  parentNames: "Maya and Jordan",
  babyName: "[Last Name]",
  dueDate: "2027-03-15",
  home: "apartment",
  hasCar: false,
  feeding: "breast",
  budget: "lean",
  values: [],
  alreadyHave: ["crib"],
  preferredRetailers: ["target"],
  notes: "",
};

const created = await call("/api/registries", { method: "POST", body: JSON.stringify({ profile }) });
check("create registry", created.status === 200, JSON.stringify(created.body).slice(0, 120));
const id = created.body.id;
const owner = await call(`/api/registries/${id}`);
const reg = owner.body.registry;
check("title from names, placeholder dropped", reg?.title === "Maya and Jordan's baby registry", `title=${reg?.title}`);
check("names stored", reg?.parentNames === "Maya and Jordan" && reg?.babyName === "", `baby=${JSON.stringify(reg?.babyName)}`);
const slug = reg.slug;

let pub = await call(`/api/r/${slug}`);
check("public: no address yet", pub.body.registry?.hasAddress === false);
let req = await call(`/api/r/${slug}/address`, { method: "POST", body: JSON.stringify({ name: "Aunt Lisa", contact: "lisa@example.com", message: "" }) });
check("request refused without address", req.status === 409, req.body.error);

const address = { recipient: "Maya Rivera", line1: "12 Elm St", line2: "Apt 4", city: "Brooklyn", region: "NY", postalCode: "11201", country: "United States" };
const saved = await call(`/api/registries/${id}/details`, {
  method: "PUT",
  body: JSON.stringify({
    details: { title: "Baby Rivera's nest", parentNames: "Maya and Jordan", babyName: "Ava", familyNote: "Thank you!" },
    address,
  }),
});
check("save details + address", saved.status === 200, JSON.stringify(saved.body));

pub = await call(`/api/r/${slug}`);
const p = pub.body.registry;
check("public shows names/note/title", p?.title === "Baby Rivera's nest" && p?.babyName === "Ava" && p?.familyNote === "Thank you!");
check("public hasAddress true", p?.hasAddress === true);
check("public never includes the address", !JSON.stringify(pub.body).includes("Elm St"));

const badAuth = await fetch(`${base}/api/registries/${id}/details`);
check("details GET needs owner", process.env.ACCESS_TOKEN ? badAuth.status === 401 : true, `status=${badAuth.status}`);

req = await call(`/api/r/${slug}/address`, { method: "POST", body: JSON.stringify({ name: "Aunt Lisa", contact: "lisa@example.com", message: "Sending the stroller!" }) });
check("request created", req.status === 200 && req.body.id && req.body.token);
const { id: requestId, token } = req.body;

let status = await call(`/api/r/${slug}/address?id=${requestId}&token=${token}`);
check("requester sees pending, no address", status.body.status === "pending" && status.body.address === null);
const wrong = await call(`/api/r/${slug}/address?id=${requestId}&token=nope`);
check("wrong token rejected", wrong.status === 404);

const list = await call(`/api/registries/${id}/details`);
check("owner sees request + address", list.body.requests?.[0]?.name === "Aunt Lisa" && list.body.address?.city === "Brooklyn");

const decided = await call(`/api/registries/${id}/details`, { method: "POST", body: JSON.stringify({ requestId, decision: "approved" }) });
check("owner approves", decided.status === 200, JSON.stringify(decided.body));
status = await call(`/api/r/${slug}/address?id=${requestId}&token=${token}`);
check("requester sees address after approval", status.body.status === "approved" && status.body.address?.line1 === "12 Elm St");

await call(`/api/registries/${id}/details`, { method: "POST", body: JSON.stringify({ requestId, decision: "declined" }) });
status = await call(`/api/r/${slug}/address?id=${requestId}&token=${token}`);
check("stop sharing hides address", status.body.status === "declined" && status.body.address === null);

console.log(`\nregistry ${id} slug ${slug}`);
console.log(failures ? `${failures} FAILED` : "ALL PASSED");
process.exit(failures ? 1 : 0);

