import { z } from "zod";

export const RETAILERS = ["amazon", "walmart", "target"] as const;
export type RetailerId = (typeof RETAILERS)[number];

export const RETAILER_LABELS: Record<RetailerId, string> = {
  amazon: "Amazon",
  walmart: "Walmart",
  target: "Target",
};

export const CATEGORIES = [
  "Sleep",
  "Feeding",
  "Diapering",
  "Bath",
  "On-the-go",
  "Clothing",
  "Health",
  "Play",
] as const;
export type Category = (typeof CATEGORIES)[number];

export const PRIORITIES = ["must-have", "nice-to-have", "later"] as const;
export type Priority = (typeof PRIORITIES)[number];

export type ItemStatus = "pending" | "keep" | "skip";

export const ParentProfileSchema = z.object({
  parentNames: z.string().describe("Parents' first names as they'd like them shown, e.g. 'Maya and Jordan'. Empty if not shared."),
  babyName: z.string().describe("Baby's name or nickname if picked. Empty if not decided or not shared."),
  dueDate: z.string().nullable(),
  home: z.enum(["apartment", "house", "unknown"]),
  hasCar: z.boolean().nullable(),
  feeding: z.enum(["breast", "formula", "both", "unsure"]),
  budget: z.enum(["lean", "moderate", "generous"]),
  values: z.array(z.string()),
  alreadyHave: z.array(z.string()),
  preferredRetailers: z.array(z.enum(RETAILERS)),
  notes: z.string(),
});
export type ParentProfile = z.infer<typeof ParentProfileSchema>;

export const GeneratedItemSchema = z.object({
  name: z.string(),
  category: z.enum(CATEGORIES),
  priority: z.enum(PRIORITIES),
  reason: z.string(),
  // No max here: models sometimes over-count, and offers.ts clamps instead of rejecting the registry.
  qty: z.number().describe("Units to register for, 1-20. Count packs or sets, e.g. 4 packs of diapers, not 200 diapers."),
  searchQuery: z.string(),
});
export type GeneratedItem = z.infer<typeof GeneratedItemSchema>;

export type Offer = {
  retailer: RetailerId;
  externalId: string;
  title: string;
  price: number | null;
  imageUrl: string | null;
  url: string;
  rating: number | null;
  inStock: boolean;
};

export type RegistryItem = {
  id: string;
  name: string;
  category: Category;
  priority: Priority;
  reason: string;
  qty: number;
  status: ItemStatus;
  position: number;
  searchQuery: string;
  offers: Array<Offer & { id: string; isPrimary: boolean }>;
  purchased: { buyerName: string | null; retailer: RetailerId | null } | null;
};

export type Registry = {
  id: string;
  slug: string;
  ownerId: string;
  title: string;
  parentNames: string;
  babyName: string;
  familyNote: string;
  /** Whether a private shipping address is on file. The address itself is never part of Registry. */
  hasAddress: boolean;
  profile: ParentProfile;
  preferredRetailers: RetailerId[];
  dueDate: string | null;
  revision: number;
  items: RegistryItem[];
};

export const DetailsSchema = z.object({
  title: z.string().trim().min(1).max(80),
  parentNames: z.string().trim().max(80),
  babyName: z.string().trim().max(40),
  familyNote: z.string().trim().max(500),
});
export type RegistryDetails = z.infer<typeof DetailsSchema>;

export const AddressSchema = z.object({
  recipient: z.string().trim().min(1).max(80),
  line1: z.string().trim().min(1).max(120),
  line2: z.string().trim().max(120),
  city: z.string().trim().min(1).max(80),
  region: z.string().trim().max(80),
  postalCode: z.string().trim().max(20),
  country: z.string().trim().max(60),
});
export type ShippingAddress = z.infer<typeof AddressSchema>;

export const AddressRequestInputSchema = z.object({
  name: z.string().trim().min(1).max(80),
  contact: z.string().trim().min(3).max(120),
  message: z.string().trim().max(300),
});

export type AddressRequestStatus = "pending" | "approved" | "declined";
export type AddressRequest = {
  id: string;
  name: string;
  contact: string;
  message: string;
  status: AddressRequestStatus;
  createdAt: string;
};

export type ChatMessage = { role: "assistant" | "user"; content: string };

export const EditDiffSchema = z.object({
  summary: z.string(),
  remove: z.array(z.string()).describe("ids of items to remove"),
  add: z.array(GeneratedItemSchema),
  swap: z
    .array(z.object({ id: z.string(), searchQuery: z.string(), reason: z.string() }))
    .describe("items to re-search with a new query"),
});
export type EditDiff = z.infer<typeof EditDiffSchema>;

/** Guidance shared by the typed chat and the voice agent, so both ask the same things. */

export const INTAKE_GUIDANCE = `You are a calm, kind registry helper for an expecting parent who is likely tired and overwhelmed.
Your job: learn just enough to build a great baby registry, in as few questions as possible (7-10 total).
Rules:
- Ask ONE short question per message. Never lecture. Never list more than one question.
- Briefly acknowledge their answer (a few words) before the next question.
- Cover, in roughly this order, skipping anything they've already told you:
  due date; names (what family should call them, e.g. "Maya and Jordan", and the baby's name if they've picked one;
  ask both in one friendly question and make clear the baby's name is optional);
  home (apartment/house); whether they drive; feeding plans; budget (lean/moderate/generous);
  things they already have or are getting handed down; values (eco-friendly, minimal, gender-neutral, etc.);
  favorite stores (Amazon, Walmart, Target).
- parentNames and babyName are only what they actually said. Never invent names or use placeholders;
  leave them empty if they skip. Never ask for a home address; they can add one privately later.
- If they say "I don't know" or "skip", pick a sensible default and move on. Reassure them that's fine.
- preferredRetailers may only contain "amazon", "walmart", "target".
- dueDate is ISO yyyy-mm-dd or null. Due dates are always in the future (within about 10 months).
  If they only name a month, use the 15th of the NEXT time that month occurs after today.`;

export const VOICE_RULES = `You are speaking out loud, not writing.
- Use short, natural spoken sentences. One question at a time.
- Never use lists, bullet points, emoji, markdown, URLs, or symbols like "$" or "%". Say "dollars" and "percent".
- Say dates the way people speak them, like "March fifteenth".
- If you didn't catch something, ask once more, gently.`;

export function todayLine() {
  return `Today is ${new Date().toISOString().slice(0, 10)}.`;
}

import "server-only";
import { z } from "zod";
import { ParentProfileSchema, type ChatMessage, type ParentProfile, type RetailerId } from "../types";
import { normalizeProfile } from "../profile";
import { callJson, isOpenAIConfigured } from "./openai";
import { INTAKE_GUIDANCE, todayLine } from "./prompts";

export const IntakeTurnSchema = z.object({
  reply: z.string().describe("Your next short, warm message. One question at a time."),
  chips: z.array(z.string()).describe("2-5 short tap-to-answer options for the question you asked"),
  done: z.boolean().describe("True once you know enough to build the registry"),
  profile: ParentProfileSchema.nullable().describe("Filled in only when done is true"),
});
export type IntakeTurn = z.infer<typeof IntakeTurnSchema>;

function systemPrompt() {
  return `${INTAKE_GUIDANCE}
- Offer 1-5 tap-to-answer chips matching your question. Each chip is sent as their answer, so it must read as one.
  For the names question, use only chips like "Skip for now" and "No baby name yet"; they'll type the names.
- When you have enough, set done=true, fill in profile, and reply with one encouraging sentence
  saying you're building their registry now.
${todayLine()}`;
}

export const OPENING: IntakeTurn = {
  reply:
    "Hi! I'll put together a registry for you, so you don't have to start from a blank page. Just a few quick questions, and you can tap an answer or type anything. First, when is your little one due?",
  chips: ["In 1-2 months", "In 3-5 months", "6+ months away", "Not sure yet"],
  done: false,
  profile: null,
};

export async function nextIntakeTurn(messages: ChatMessage[]): Promise<IntakeTurn> {
  if (!isOpenAIConfigured()) return mockIntakeTurn(messages);
  const turn = await callJson("intake_turn", IntakeTurnSchema, [{ role: "system", content: systemPrompt() }, ...messages]);
  if (turn.profile) turn.profile = normalizeProfile(turn.profile);
  return turn;
}

