"use client";

import Link from "next/link";
import { use, useMemo, useState } from "react";
import { AuthGate } from "@/components/AuthGate";
import { ItemCard } from "@/components/ItemCard";
import { ProductPhoto } from "@/components/ProductPhoto";
import { Status } from "@/components/Status";
import { useRegistry } from "@/components/useRegistry";
import { CATEGORIES, type Category } from "@/lib/types";

export default function ReviewPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  return (
    <AuthGate>
      <Review id={id} />
    </AuthGate>
  );
}

type Group = { category: Category; items: unknown[]; pending: Array<{ id: string }> };

function Review({ id }: { id: string }) {
  const { registry, error, setStatus, setPrimary } = useRegistry(id);
  const [category, setCategory] = useState<Category | null>(null);

  const groups = useMemo(() => {
    if (!registry) return [];
    return CATEGORIES.map((c) => {
      const items = registry.items.filter((i) => i.category === c);
      return { category: c, items, pending: items.filter((i) => i.status === "pending") };
    }).filter((g) => g.items.length > 0);
  }, [registry]);

  if (error && !registry) return <Status tone="error">{error}</Status>;
  if (!registry) return <Status>Opening your registry…</Status>;

  const total = registry.items.length;
  const reviewed = registry.items.filter((i) => i.status !== "pending").length;
  const progress = total ? reviewed / total : 0;
  const active = category ? groups.find((g) => g.category === category) : null;
  const current = active?.pending[0];

  const header = (
    <header className="sticky top-0 z-10 -mx-4 space-y-3 bg-bg px-4 pt-5 pb-4 sm:-mx-6 sm:px-6">
      <div className="flex items-center justify-between text-[13px]">
        {active ? (
          <button onClick={() => setCategory(null)} className="link">
            All categories
          </button>
        ) : (
          <Link href={`/registry/${id}`} className="link">
            Registry overview
          </Link>
        )}
        <span className="text-muted tabular-nums">
          {reviewed} of {total} reviewed
        </span>
      </div>
      <div
        className="h-1 overflow-hidden rounded-full bg-line"
        role="progressbar"
        aria-valuenow={reviewed}
        aria-valuemax={total}
        aria-label="Review progress"
      >
        <div className="h-full rounded-full bg-accent transition-[width] duration-500" style={{ width: `${progress * 100}%` }} />
      </div>
    </header>
  );

  if (active) {
    return (
      <main className="space-y-5">
        {header}
        {current && (
          <div className="flex items-baseline justify-between">
            <h1 className="font-serif text-[21px] font-semibold">{active.category}</h1>
            <span className="text-[13px] text-muted tabular-nums">
              {active.items.length - active.pending.length + 1} of {active.items.length}
            </span>
          </div>
        )}

        {current ? (
          <ItemCard key={current.id} item={current} onChooseOffer={(offerId) => void setPrimary(current.id, offerId)}>
            <div className="sticky bottom-0 -mx-4 grid grid-cols-2 gap-3 bg-bg px-4 pt-3 pb-[max(1rem,env(safe-area-inset-bottom))] sm:-mx-6 sm:px-6 md:static md:mx-0 md:px-0 md:pt-4 md:pb-0">
              <button className="btn-quiet" onClick={() => void setStatus(current.id, "skip")}>
                Skip
              </button>
              <button className="btn-primary" onClick={() => void setStatus(current.id, "keep")}>
                Keep
              </button>
            </div>
          </ItemCard>
        ) : (
          <div className="space-y-8 pt-6 lg:pt-10">
            <div className="space-y-2">
              <h1 className="font-serif text-[26px] font-semibold lg:text-[41px]">{active.category} is reviewed.</h1>
              <p className="text-muted lg:text-[17px]">
                You kept {active.items.filter((i) => i.status === "keep").length} of {active.items.length} items.
              </p>
            </div>
            <ul className="grid grid-cols-3 gap-3 sm:grid-cols-4 lg:grid-cols-6 lg:gap-5">
              {active.items
                .filter((i) => i.status === "keep")
                .map((item) => (
                  <li key={item.id} className="space-y-2">
                    <ProductPhoto offer={item.offers[0]} label={item.name} className="aspect-square w-full" />
                    <p className="truncate text-[13px]">{item.name}</p>
                  </li>
                ))}
            </ul>
            <div className="sm:max-w-sm">
              <NextStep groups={groups} onPick={setCategory} id={id} />
            </div>
          </div>
        )}
      </main>
    );
  }

  return (
    <main className="space-y-8">
      {header}
      <div className="space-y-3">
        <h1 className="font-serif text-[33px] leading-tight font-semibold lg:text-[48px]">{registry.title}</h1>
        <p className="max-w-[60ch] text-muted lg:text-[17px]">
          Your full draft is ready. Go through it one category at a time, in any order. Stop whenever you like, your
          progress is saved.
        </p>
      </div>

      <ul className="border-t border-line">
        {groups.map((g) => {
          const done = g.pending.length === 0;
          const minutes = Math.max(1, Math.round(g.pending.length / 3));
          return (
            <li key={g.category} className="border-b border-line">
              <button
                onClick={() => setCategory(g.category)}
                className="group flex w-full items-center justify-between gap-6 py-4 text-left lg:py-5"
              >
                <span className="font-serif text-[21px] transition-colors group-hover:text-accent lg:w-48 lg:shrink-0 lg:text-[26px]">
                  {g.category}
                </span>
                <span className="hidden flex-1 gap-3 lg:flex" aria-hidden>
                  {g.items.slice(0, 7).map((item) => (
                    <ProductPhoto
                      key={item.id}
                      offer={item.offers[0]}
                      label=""
                      className={`h-16 w-16 rounded-[10px] ${item.status === "skip" ? "opacity-30" : ""}`}
                    />
                  ))}
                </span>
                <span className="shrink-0 text-[13px] text-muted tabular-nums lg:text-[14px]">
                  {done ? "Reviewed" : `${g.pending.length} to review, about ${minutes} min`}
                </span>
              </button>
            </li>
          );
        })}
      </ul>

      {progress === 1 && (
        <Link href={`/registry/${id}`} className="btn-primary w-full sm:w-auto sm:px-8">
          See and share your registry
        </Link>
      )}
    </main>
  );
}

function NextStep({ groups, onPick, id }: { groups: Group[]; onPick: (c: Category | null) => void; id: string }) {
  const next = groups.find((g) => g.pending.length > 0);
  if (!next) {
    return (
      <Link href={`/registry/${id}`} className="btn-primary w-full">
        See and share your registry
      </Link>
    );
  }
  return (
    <button className="btn-primary w-full" onClick={() => onPick(next.category)}>
      Review {next.category}
    </button>
  );
}

import "server-only";
import { z } from "zod";
import { INTAKE_GUIDANCE, todayLine, VOICE_RULES } from "../ai/prompts";
import { ParentProfileSchema, type ChatMessage, type Registry } from "../types";

export const AGENT_URL = "wss://agent.deepgram.com/v1/agent/converse";

export function isVoiceConfigured() {
  return Boolean(process.env.DEEPGRAM_API_KEY);
}

/** Mints a 30-second token the browser uses to open the agent socket. The API key needs Member permission. */
export async function grantToken(): Promise<string> {
  const response = await fetch("https://api.deepgram.com/v1/auth/grant", {
    method: "POST",
    headers: { authorization: `Token ${process.env.DEEPGRAM_API_KEY}` },
  });
  if (!response.ok) throw new Error(`Deepgram token request failed (${response.status}): ${(await response.text()).slice(0, 200)}`);
  return ((await response.json()) as { access_token: string }).access_token;
}

const KEYTERMS = ["bassinet", "swaddle", "onesie", "stroller", "car seat", "Target", "Walmart", "Amazon"];

function profileParameters() {
  const { $schema: _schema, ...schema } = z.toJSONSchema(ParentProfileSchema) as Record<string, unknown>;
  return schema;
}

function baseSettings(mode: "intake" | "edit", prompt: string, functions: unknown[], greeting: string, history: ChatMessage[] = []) {
  return {
    type: "Settings",
    tags: ["calm-registry", mode],
    audio: {
      input: { encoding: "linear16", sample_rate: 16000 },
      output: { encoding: "linear16", sample_rate: 24000, container: "none" },
    },
    agent: {
      ...(history.length && {
        context: { messages: history.map((m) => ({ type: "History", role: m.role, content: m.content })) },
      }),
      listen: { provider: { type: "deepgram", model: "flux-general-en", version: "v2", keyterms: KEYTERMS } },
      think: {
        provider: { type: "open_ai", model: "gpt-4o-mini", temperature: 0.4 },
        prompt: `${prompt}\n\n${VOICE_RULES}\n${todayLine()}`,
        functions,
      },
      speak: { provider: { type: "deepgram", version: "v2", model: "flux-alexis-en", speed: 0.95 } },
      greeting,
    },
  };
}

const VOICE_OPENING =
  "Hi! I'll put together a registry for you, so you don't have to start from a blank page. Just a few quick questions. First, when is your little one due?";

export function intakeSettings(history: ChatMessage[]) {
  const answered = history.some((m) => m.role === "user");
  const lastAssistant = [...history].reverse().find((m) => m.role === "assistant")?.content;
  const greeting = answered && lastAssistant ? `Okay, I'm listening. ${lastAssistant}` : VOICE_OPENING;
  const prompt = `${INTAKE_GUIDANCE}
- When you know enough, or the parent asks to finish, call finish_intake with the complete profile.
  Use "unknown", "unsure", null, or an empty list for anything you didn't learn. Don't announce the call first.
- After finish_intake succeeds, say one short, warm sentence that you're building their registry now, then stop talking.
- If finish_intake reports a problem, ask only about what it says is missing.`;
  const functions = [
    {
      name: "finish_intake",
      description: "Build the parent's registry from everything learned in the conversation.",
      parameters: profileParameters(),
      defer_until_eot: true,
    },
  ];
  // Without the opening chat message, history would start with a user turn the agent never asked for.
  return { settings: baseSettings("intake", prompt, functions, greeting, answered ? history : []), greeting };
}

export function editSettings(registry: Registry) {
  const items = registry.items
    .filter((i) => i.status !== "skip")
    .map((i) => ({
      name: i.name,
      category: i.category,
      price: i.offers[0]?.price ?? null,
      qty: i.qty,
      purchased: Boolean(i.purchased),
    }));
  const prompt = `You help an expecting parent change their baby registry, "${registry.title}", by talking.
Current items (JSON): ${JSON.stringify(items)}
How to work:
- Whenever they ask to add, remove, swap, or change anything, immediately call preview_change with their request in plain words.
  Don't confirm first and don't decide yourself whether it's possible; preview_change works that out.
- Then read its summary back in one or two sentences and ask if you should make the change.
- If they agree, call apply_change. If they don't, call cancel_change. Only one change can wait at a time.
- You may answer simple questions about the list from the items above without calling a function.
- Never claim a change was made unless apply_change succeeded.
- When they say they're done, say a short goodbye.`;
  const functions = [
    {
      name: "preview_change",
      description: "Propose a change to the registry and show it on screen. Returns a summary to read back.",
      parameters: {
        type: "object",
        properties: { request: { type: "string", description: "The change the parent wants, in plain words." } },
        required: ["request"],
      },
    },
    {
      name: "apply_change",
      description: "Apply the change that was previewed, after the parent agrees.",
      parameters: { type: "object", properties: {} },
      defer_until_eot: true,
    },
    {
      name: "cancel_change",
      description: "Discard the previewed change.",
      parameters: { type: "object", properties: {} },
    },
  ];
  const greeting = "I'm listening. What would you like to change?";
  return { settings: baseSettings("edit", prompt, functions, greeting), greeting };
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { api } from "@/lib/client";
import type { ItemStatus, Registry } from "@/lib/types";

export function useRegistry(id: string) {
  const [registry, setRegistry] = useState<Registry | null>(null);
  const [error, setError] = useState("");

  const reload = useCallback(async () => {
    try {
      const { registry } = await api<{ registry: Registry }>(`/api/registries/${id}`);
      setRegistry(registry);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Could not load registry.");
    }
  }, [id]);

  useEffect(() => {
    void reload();
  }, [reload]);

  const setStatus = useCallback(
    async (itemId: string, status: ItemStatus) => {
      setRegistry((r) => r && { ...r, items: r.items.map((i) => (i.id === itemId ? { ...i, status } : i)) });
      await api(`/api/registries/${id}`, { method: "PATCH", body: JSON.stringify({ action: "status", itemId, status }) }).catch(
        (e: Error) => setError(e.message),
      );
    },
    [id],
  );

  const setPrimary = useCallback(
    async (itemId: string, offerId: string) => {
      setRegistry(
        (r) =>
          r && {
            ...r,
            items: r.items.map((i) =>
              i.id === itemId
                ? {
                    ...i,
                    offers: i.offers
                      .map((o) => ({ ...o, isPrimary: o.id === offerId }))
                      .sort((a, b) => Number(b.isPrimary) - Number(a.isPrimary)),
                  }
                : i,
            ),
          },
      );
      await api(`/api/registries/${id}`, { method: "PATCH", body: JSON.stringify({ action: "primary", itemId, offerId }) }).catch(
        (e: Error) => setError(e.message),
      );
    },
    [id],
  );

  return { registry, error, reload, setStatus, setPrimary };
}

"use client";

import { useCallback, useEffect, useState } from "react";
